string D="ArtSource/Pipeline/Review/BriarwickEnvironment05";var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(s.path!="Assets/Scenes/Briarwick_Hamlet_Dev01.unity"||s.isDirty||EditorApplication.isPlaying)throw new System.Exception("Saved Briarwick Edit only");
string Path(Transform t){return t.parent==null?t.name:Path(t.parent)+"/"+t.name;}
var snapshot=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Select(t=>new{path=Path(t),active=t.gameObject.activeSelf,components=t.GetComponents<Component>().Where(c=>c!=null).Select(c=>new{type=c.GetType().FullName,json=EditorJsonUtility.ToJson(c)}).ToArray()}).ToArray();System.IO.File.WriteAllText(D+"/SceneBefore.json",Newtonsoft.Json.JsonConvert.SerializeObject(snapshot));
var terrain=Terrain.activeTerrain;var height=terrain.terrainData.GetHeights(0,0,terrain.terrainData.heightmapResolution,terrain.terrainData.heightmapResolution);System.IO.File.WriteAllBytes(D+"/HeightBefore.bin",height.Cast<float>().SelectMany(v=>System.BitConverter.GetBytes(v)).ToArray());
var alpha=terrain.terrainData.GetAlphamaps(0,0,terrain.terrainData.alphamapWidth,terrain.terrainData.alphamapHeight);System.IO.File.WriteAllBytes(D+"/AlphamapsBefore.bin",alpha.Cast<float>().SelectMany(v=>System.BitConverter.GetBytes(v)).ToArray());return new{scene=s.path,snapshotObjects=snapshot.Length};